	static Stream<Arguments> stackRoutes() {
		List<Arguments> arguments = new ArrayList<>();
		for (Stack stack : Stack.values()) {
			for (Route route : Route.values()) {
				arguments.add(Arguments.of(stack, route));
			}
		}
		return arguments.stream();
	}

	@ParameterizedTest
	@MethodSource("stackRoutes")
	void repositoryRoutesExposeReadyValuesThroughWrapperStack(Stack stack, Route route, @TempDir File directory) {
		seed(directory, 1);
		LmdbStore store = newStore(directory);
		AtomicInteger probeRows = new AtomicInteger();
		SailRepository repository;
		if (stack == Stack.PROBE) {
			ProbeSail probe = new ProbeSail(store, -1);
			probeRows = probe.rows;
			repository = new SailRepository(probe);
		} else {
			DelegatingProbeSail delegating = new DelegatingProbeSail(store, WrapperMode.PASS_THROUGH);
			probeRows = delegating.rows;
			repository = new SailRepository(delegating);
		}
		List<Value> retained = new ArrayList<>();
		repository.init();
		RepositoryValueExposureStats statsBefore = store.getRepositoryValueExposureStats();
		try (RepositoryConnection connection = repository.getConnection()) {
			switch (route) {
			case STATEMENTS:
				try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
					while (statements.hasNext()) {
						retainReadyStatement(statements.next(), retained);
					}
				}
				break;
			case CONTEXTS:
				try (RepositoryResult<Resource> contexts = connection.getContextIDs()) {
					while (contexts.hasNext()) {
						Value context = contexts.next();
						assertDeepReady(context);
						retained.add(context);
					}
				}
				break;
			case TUPLE:
				try (TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
					while (result.hasNext()) {
						retainReady(result.next().getValue("value"), retained);
					}
				}
				break;
			case GRAPH:
				try (GraphQueryResult result = connection.prepareGraphQuery(CONSTRUCT).evaluate()) {
					while (result.hasNext()) {
						retainReadyStatement(result.next(), retained);
					}
				}
				break;
			case NAMESPACES:
				try (RepositoryResult<Namespace> namespaces = connection.getNamespaces()) {
					assertTrue(namespaces.hasNext());
					assertEquals("urn:repository-exposure:", namespaces.next().getName());
					assertFalse(namespaces.hasNext());
				}
				break;
			case EXPORT:
				connection.export(new AbstractRDFHandler() {
					@Override
					public void handleStatement(Statement statement) {
						retainReadyStatement(statement, retained);
					}
				});
				break;
			case TUPLE_HANDLER:
				connection.prepareTupleQuery(SELECT).evaluate(new AbstractTupleQueryResultHandler() {
					@Override
					public void handleSolution(BindingSet bindings) {
						retainReady(bindings.getValue("value"), retained);
					}
				});
				break;
			case GRAPH_HANDLER:
				connection.prepareGraphQuery(CONSTRUCT).evaluate(new AbstractRDFHandler() {
					@Override
					public void handleStatement(Statement statement) {
						retainReadyStatement(statement, retained);
					}
				});
				break;
			}
			assertTrue(probeRows.get() > 0, "The wrapper stack must participate in outward retrieval");
			// CONSTRUCT converts the evaluate rows into statements before exposure, which is not a pass-through.
			if (stack == Stack.DELEGATING && route != Route.GRAPH && route != Route.GRAPH_HANDLER) {
				assertEquals(0, delta(statsBefore, store.getRepositoryValueExposureStats()).exposuresOpaque(),
						"A pass-through delegating stack must never fall back to an opaque exposure");
			}
		} finally {
			repository.shutDown();
		}
		retained.forEach(LmdbRepositoryValueExposureTest::assertDeepReady);
		retained.forEach(Value::stringValue);
	}

	@Test
	void delegatingConnectionWithPassThroughWrappersBindsRepositoryExposure(@TempDir File directory) {
		seed(directory, 3);
		LmdbStore store = newStore(directory);
		// The second query may reuse values the first one already made ready, so laziness is not asserted here.
		DelegatingProbeSail delegating = new DelegatingProbeSail(store, WrapperMode.PASS_THROUGH, false);
		SailRepository repository = new SailRepository(delegating);
		repository.init();
		List<Value> retained = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			RepositoryValueExposureStats before = store.getRepositoryValueExposureStats();
			int rowsBefore = delegating.rows.get();
			try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
				while (statements.hasNext()) {
					retainReadyStatement(statements.next(), retained);
				}
			}
			RepositoryValueExposureStats statementsDelta = delta(before, store.getRepositoryValueExposureStats());
			assertTrue(delegating.rows.get() > rowsBefore, "The pass-through wrapper must see the rows");
			assertTrue(statementsDelta.exposuresBound() >= 1, "getStatements must bind: " + statementsDelta);
			assertEquals(0, statementsDelta.exposuresOpaque(), "getStatements must not be opaque");
			assertEquals(0, statementsDelta.externalValueProtections(), "getStatements must skip protection");

			before = store.getRepositoryValueExposureStats();
			rowsBefore = delegating.rows.get();
			try (TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
				while (result.hasNext()) {
					retainReady(result.next().getValue("value"), retained);
				}
			}
			RepositoryValueExposureStats queryDelta = delta(before, store.getRepositoryValueExposureStats());
			assertTrue(delegating.rows.get() > rowsBefore, "The pass-through wrapper must see the rows");
			assertTrue(queryDelta.exposuresBound() >= 1, "SELECT must bind: " + queryDelta);
			assertEquals(0, queryDelta.exposuresOpaque(), "SELECT must not be opaque");
			assertEquals(0, queryDelta.externalValueProtections(), "SELECT must skip protection");
		} finally {
			repository.shutDown();
		}
		retained.forEach(LmdbRepositoryValueExposureTest::assertDeepReady);
		retained.forEach(LmdbRepositoryValueExposureTest::assertUnpromoted);
	}

