	@Test
	void nestedRawReadThroughDelegatingStackKeepsItsIndependentColdOwnership(@TempDir File directory) {
		seed(directory, 1);
		LmdbStore store = newStore(directory);
		DelegatingProbeSail delegating = new DelegatingProbeSail(store, WrapperMode.PASS_THROUGH, false);
		SailRepository repository = new SailRepository(delegating);
		repository.init();
		AtomicReference<SailConnection> innerConnection = new AtomicReference<>();
		AtomicReference<Value> escaped = new AtomicReference<>();
		AtomicInteger callbacks = new AtomicInteger();
		String functionIRI = "urn:repository-exposure:delegating-nested-raw:" + UUID.randomUUID();
		Function function = new Function() {
			@Override
			public String getURI() {
				return functionIRI;
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				throw new AssertionError("The real query callback must receive its TripleSource");
			}

			@Override
			public Value evaluate(TripleSource source, Value... args) {
				callbacks.incrementAndGet();
				try (CloseableIteration<? extends Statement> rows = innerConnection.get()
						.getStatements(SUBJECT, PREDICATE, null, false, CONTEXT)) {
					assertTrue(rows.hasNext());
					Value parent = rows.next().getObject();
					assertFalse(((LmdbValue) parent).isInitialized());
					Value child = ((TripleTerm) parent).getObject();
					assertFalse(((LmdbValue) child).isInitialized());
					escaped.set(child);
					assertFalse(rows.hasNext());
				}
				return VF.createLiteral("outer-row");
			}
		};
		FunctionRegistry.getInstance().add(function);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				innerConnection.set(((DelegatingProbeSail.DelegatingConnection) ((SailRepositoryConnection) connection)
						.getSailConnection()).inner);
				RepositoryValueExposureStats before = store.getRepositoryValueExposureStats();
				try (TupleQueryResult result = connection.prepareTupleQuery(
						"SELECT (<" + functionIRI + ">() AS ?value) WHERE {}").evaluate()) {
					assertTrue(result.hasNext());
					assertEquals("outer-row", result.next().getValue("value").stringValue());
					assertFalse(result.hasNext());
				}
				RepositoryValueExposureStats delta = delta(before, store.getRepositoryValueExposureStats());
				assertTrue(delta.exposuresBound() >= 1, "The outer query must bind: " + delta);
				assertEquals(0, delta.exposuresOpaque(), "The outer query must not be opaque");
				assertTrue(delta.externalValueProtections() > 0,
						"The nested raw read must use the conservative path: " + delta);
			}
			assertEquals(1, callbacks.get());
			Value child = escaped.get();
			assertFalse(((LmdbValue) child).isInitialized());
			try (SailConnection writer = store.getConnection()) {
				for (int round = 0; round < 3; round++) {
					writer.begin(IsolationLevels.READ_COMMITTED);
					writer.clear();
					writer.addStatement(VF.createIRI("urn:nested-raw:replacement:" + round), PREDICATE,
							VF.createLiteral("replacement " + round));
					writer.commit();
				}
			}
			assertFalse(((LmdbValue) child).isInitialized());
			assertEquals(VF.createTripleTerm(SUBJECT, PREDICATE,
					VF.createLiteral("nested outward value 0", DATATYPE)), child);
		} finally {
			FunctionRegistry.getInstance().remove(function);
			repository.shutDown();
		}
	}

	@Test
	@Timeout(10)
	void passThroughCycleIsOpaqueAndTerminates(@TempDir File directory) {
		seed(directory, 1);
		LmdbStore store = newStore(directory);
		store.init();
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			LinkedPassThrough<Statement> first = new LinkedPassThrough<>();
			LinkedPassThrough<Statement> second = new LinkedPassThrough<>();
			first.target = second;
			second.target = first;
			RepositoryValueExposureStats before = store.getRepositoryValueExposureStats();
			CloseableIteration<? extends Statement> exposed = connection.exposeIteration(first,
					SailResultValueExtractor.STATEMENTS);
			exposed.close();
			RepositoryValueExposureStats delta = delta(before, store.getRepositoryValueExposureStats());
			assertEquals(1, delta.exposuresOpaque());
			assertEquals(0, delta.exposuresBound());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void passThroughDepthIsLimitedToSixteenHops(@TempDir File directory) {
		seed(directory, 2);
		LmdbStore store = newStore(directory);
		store.init();
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			assertEquals(1, exposeThroughLayers(store, connection, 16).exposuresBound(),
					"A registered result 16 hops away must still bind");
			RepositoryValueExposureStats beyond = exposeThroughLayers(store, connection, 17);
			assertEquals(0, beyond.exposuresBound(), "A registered result 17 hops away must not bind");
			assertEquals(1, beyond.exposuresOpaque());
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(30)
	void failedBindingReleasesTheRepositoryResultScope(@TempDir File directory) {
		seed(directory, 1);
		LmdbStore store = newStore(directory);
		store.init();
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			ValueStore values = (ValueStore) store.getBackingStore().getValueFactory();
			int scopesBefore = values.valueResolutionScopeCountForTest();
			IllegalStateException injected = new IllegalStateException("injected passThroughSource failure");
			AtomicInteger closes = new AtomicInteger();
			CloseableIteration<Statement> source = new ThrowingPassThrough<>(injected, closes);
			IllegalStateException thrown = assertThrows(IllegalStateException.class,
					() -> connection.exposeIteration(source, SailResultValueExtractor.STATEMENTS));
			assertSame(injected, thrown);
			assertEquals(1, closes.get(), "A failed exposure must close its source exactly once");
			assertEquals(scopesBefore, values.valueResolutionScopeCountForTest(),
					"A failed exposure must close the result scope it opened");
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(value = WrapperMode.class, names = { "PASS_THROUGH", "OPAQUE" })
	@Timeout(60)
	void boundResultClosedBeforeValueResolutionStillResolvesTheRow(WrapperMode mode, @TempDir File directory)
			throws Exception {
		seed(directory, 1);
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig().setInlineLiterals(false)
				.setAsyncValueCleanup(true)
				.setValueOverlayEnabled(false)
				.setValueCacheSize(64)
				.setAsyncValueCleanupBatchSize(1));
		DelegatingProbeSail delegating = new DelegatingProbeSail(store, mode, false);
		SailRepository repository = new SailRepository(delegating);
		repository.init();
		LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
		AtomicReference<String> rewrite = new AtomicReference<>("not attempted");
		try (RepositoryConnection connection = repository.getConnection()) {
			SailConnection outer = ((SailRepositoryConnection) connection).getSailConnection();
			CloseableIteration<? extends Statement> source = outer.getStatements(SUBJECT, PREDICATE, null, false,
					CONTEXT);
			AtomicInteger snapshots = new AtomicInteger();
			SailResultValueExtractor<Statement> extractor = new SailResultValueExtractor<>() {
				@Override
				public void extract(Statement element, Consumer<Value> roots) {
					SailResultValueExtractor.STATEMENTS.extract(element, roots);
				}

				@Override
				public Statement snapshot(Statement element) {
					Statement copy = SailResultValueExtractor.STATEMENTS.snapshot(element);
					if (snapshots.getAndIncrement() == 0) {
						// The source pull has returned but the row's values are not resolved yet. This is where a
						// concurrent close of the delegating connection lands: the bound LMDB result closes, then
						// writers try to reclaim the row's dictionary entries.
						assertFalse(((LmdbValue) copy.getObject()).isInitialized(), "the row must still be cold");
						source.close();
						rewrite.set(rewriteInAnotherThread(store));
					}
					return copy;
				}
			};
			RepositoryValueExposureStats before = store.getRepositoryValueExposureStats();
			try (CloseableIteration<? extends Statement> exposed = ((SailResultValueExposure) outer)
					.exposeIteration(source, extractor)) {
				assertTrue(exposed.hasNext());
				Statement row = exposed.next();
				assertDeepReady(row.getObject());
				assertEquals(VF.createTripleTerm(SUBJECT, PREDICATE, VF.createTripleTerm(SUBJECT, PREDICATE,
						VF.createLiteral("nested outward value 0", DATATYPE))), row.getObject(),
						"rewrite: " + rewrite.get());
			}
			RepositoryValueExposureStats delta = delta(before, store.getRepositoryValueExposureStats());
			if (mode == WrapperMode.PASS_THROUGH) {
				assertEquals(1, delta.exposuresBound(), "the probe must take the bound path: " + delta);
			} else {
				assertEquals(1, delta.exposuresOpaque(), "the probe must take the opaque path: " + delta);
			}
		} finally {
			repository.shutDown();
		}
	}

	/** Clears and rewrites the store from a separate thread; returns how far it got within a bounded wait. */
	private static String rewriteInAnotherThread(LmdbStore store) {
		AtomicReference<String> outcome = new AtomicReference<>("started");
		Thread writer = new Thread(() -> {
			try (SailConnection connection = store.getConnection()) {
				for (int round = 0; round < 3; round++) {
					connection.begin(IsolationLevels.READ_COMMITTED);
					connection.clear();
					connection.addStatement(VF.createIRI("urn:closed-bound-result:replacement:" + round), PREDICATE,
							VF.createLiteral("replacement " + round));
					connection.commit();
					outcome.set("committed " + (round + 1));
				}
				AsyncValueRetirementCoordinator cleanup = store.getBackingStore().asyncValueCleanupCoordinator();
				outcome.set(outcome.get() + ", cleanupEmpty=" + cleanup.awaitEmpty(10, TimeUnit.SECONDS));
				LmdbGcTestMaintenance.drainRetirements(store.getBackingStore());
				int reclaimed = LmdbGcTestMaintenance.reclaimUnusedValues(store, 1_000_000);
				outcome.set(outcome.get() + ", reclaimed=" + reclaimed);
				connection.begin(IsolationLevels.READ_COMMITTED);
				for (int i = 0; i < 32; i++) {
					connection.addStatement(VF.createIRI("urn:closed-bound-result:reuse:" + i), PREDICATE,
							VF.createLiteral("reused id payload " + i, DATATYPE));
				}
				connection.commit();
				outcome.set(outcome.get() + ", reused");
			} catch (IOException | InterruptedException failure) {
				outcome.set("failed: " + failure);
			} catch (RuntimeException | Error failure) {
				outcome.set("failed: " + failure);
			}
		}, "closed-bound-result-writer");
		writer.setDaemon(true);
		writer.start();
		try {
			writer.join(TimeUnit.SECONDS.toMillis(10));
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
		}
		return writer.isAlive() ? "blocked after " + outcome.get() : outcome.get();
	}

	/** A pass-through source whose chain walk fails, so exposure binding throws after the exposure was built. */
	private static final class ThrowingPassThrough<T> implements CloseableIteration<T>, RowPassThroughIteration {
		private final RuntimeException failure;
		private final AtomicInteger closes;

		private ThrowingPassThrough(RuntimeException failure, AtomicInteger closes) {
			this.failure = failure;
			this.closes = closes;
		}

		@Override
		public CloseableIteration<?> passThroughSource() {
			throw failure;
		}

		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public T next() {
			throw new NoSuchElementException();
		}

		@Override
		public void close() {
			closes.incrementAndGet();
		}
	}

	private static RepositoryValueExposureStats exposeThroughLayers(LmdbStore store, LmdbStoreConnection connection,
			int layers) {
		CloseableIteration<? extends Statement> source = connection.getStatements(null, null, null, false);
		for (int layer = 0; layer < layers; layer++) {
			source = new PassThroughProbe<Statement>(source, null, null);
		}
		RepositoryValueExposureStats before = store.getRepositoryValueExposureStats();
		try (CloseableIteration<? extends Statement> exposed = connection.exposeIteration(source,
				SailResultValueExtractor.STATEMENTS)) {
			int rows = 0;
			while (exposed.hasNext()) {
				assertDeepReady(exposed.next().getObject());
				rows++;
			}
			assertEquals(2, rows);
		}
		return delta(before, store.getRepositoryValueExposureStats());
	}

	private static RepositoryValueExposureStats delta(RepositoryValueExposureStats before,
			RepositoryValueExposureStats after) {
		return new RepositoryValueExposureStats(after.exposuresBound() - before.exposuresBound(),
				after.exposuresOpaque() - before.exposuresOpaque(),
				after.externalValueProtections() - before.externalValueProtections());
	}

